const o: { readonly n: number } = { n: 1 }
o.n = 2
console.log(o.n)

class A {
  constructor(public n: number) {}
}
console.log(new A(4).n)

class A {}
class B extends A {}
console.log(new B() instanceof A)

interface I { n: number }
class A implements I { n = 1 }
try {
  console.log(new A() instanceof I)
} catch {
  console.log(0)
}

function f(x: string): number
function f(x: number): number
function f(x: string | number) {
  return typeof x === "string" ? 1 : 2
}
console.log(f(0))

class A { static n = 1 }
console.log(A.n)
console.log(new A().n)

interface I { n: number }
class A implements I { n = 7 }
console.log(new A().n)

class A {
  n = 2
  m = () => this.n
}
const m = new A().m
console.log(m())
